#!/usr/bin/env python3
"""Certified sharing replay entry point.

Reads one UTF-8 JSON request from stdin to EOF, validates the WHOLE request
(including the transactions that follow restores), replays every case and
writes a single compact JSON response to stdout.  Diagnostics go to stderr.
"""
import json
import math
import os
import sys

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)

MAX_BYTES = 8 * 1024 * 1024


def _emit_float(value, out):
    if value != value or value in (math.inf, -math.inf):
        raise ValueError('non-finite numeric result')
    if value == 0.0:
        out.append('0.0')
    else:
        out.append(repr(value))


def _emit(value, out):
    kind = type(value)
    if kind is dict:
        out.append('{')
        first = True
        for key, item in value.items():
            if not first:
                out.append(',')
            first = False
            out.append(json.dumps(key))
            out.append(':')
            _emit(item, out)
        out.append('}')
    elif kind is list:
        out.append('[')
        for index, item in enumerate(value):
            if index:
                out.append(',')
            _emit(item, out)
        out.append(']')
    elif kind is bool:
        out.append('true' if value else 'false')
    elif kind is int:
        out.append(str(value))
    elif kind is float:
        _emit_float(value, out)
    elif value is None:
        out.append('null')
    elif kind is str:
        out.append(json.dumps(value))
    else:
        raise TypeError('unsupported result value')


def serialize(value):
    out = []
    _emit(value, out)
    return ''.join(out)


def solve(request):
    from te.session import run_case
    return {'cases': [run_case(case) for case in request['cases']]}


def read_request():
    stream = getattr(sys.stdin, 'buffer', None)
    if stream is None:
        return sys.stdin.read()
    return stream.read()


def main():
    raw = read_request()
    result = None
    try:
        from protocol import InvalidRequest, loads, validate
        try:
            result = solve(validate(loads(raw)))
        except InvalidRequest:
            result = {'error': 'invalid_request'}
    except BaseException:                     # pragma: no cover - safety net
        result = {'error': 'invalid_request'}
    try:
        text = serialize(result)
    except BaseException:                     # pragma: no cover - safety net
        text = '{"error":"invalid_request"}'
    sys.stdout.write(text)
    sys.stdout.write('\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
